script:
(function () {
  'use strict';
  // Return on a stock you bought and sold (or still hold at a current price):
  //   cost basis = shares x purchase price + purchase commission
  //   net proceeds = shares x sale price - sale commission
  //   capital gain = net proceeds - cost basis;  total profit = capital gain + cash dividends
  //   total return = total profit / cost basis
  //   annualized return = (1 + total return)^(365 / days held) - 1
  //   break-even sale price = (cost basis + sale commission) / shares
  // Long-term when the sale date is after the one-year anniversary of the purchase date (held more
  // than one year, IRS Publication 550 / Topic 409), otherwise short-term.
  // Optional flat tax rate applies to a positive capital gain only (dividends are taxed separately).
  // Checked in Node (sr.test.js): 100 shares $50 -> $68, $5 + $5 commission, $240 dividends,
  // 2023-03-15 to 2025-09-15 (915 days): basis $5,005, proceeds $6,795, gain $1,790, profit $2,030,
  // total return 40.5594%, annualized 14.5467%, break-even $50.10, long-term; 2024-01-10 to
  // 2025-01-10 is short-term (exactly one year), 2025-01-11 long-term; 20 shares $100 -> $80 no
  // fees = -$400, -20%; 15% tax on a $1,790 gain = $268.50.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var DAY = 86400000;
  var OUTPUTS = ['srTotalPct', 'srAnnual', 'srGain', 'srProfit', 'srBasis', 'srProceeds', 'srGainPct', 'srDivPct',
    'srBreakeven', 'srHeld', 'srTerm', 'srTax', 'srAfterTax', 'srAfterTaxPct'];

  // --- calc start
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var t = Date.UTC(+m[1], +m[2] - 1, +m[3]);
    return isFinite(t) ? { t: t, y: +m[1], m: +m[2] - 1, d: +m[3] } : null;
  }

  // Held more than one year: the sale falls after the purchase's one-year anniversary.
  function isLongTerm(buy, sell) {
    return sell.t > Date.UTC(buy.y + 1, buy.m, buy.d);
  }

  function stockReturn(p) {
    var basis = p.shares * p.buyPrice + p.buyFee;
    var proceeds = p.shares * p.sellPrice - p.sellFee;
    var gain = proceeds - basis, profit = gain + p.dividends;
    var total = profit / basis;
    var annual = null;
    if (p.days && p.days > 0) annual = 1 + total <= 0 ? -1 : Math.pow(1 + total, 365 / p.days) - 1;
    var tax = gain > 0 ? gain * p.taxRate : 0;
    return {
      basis: basis, proceeds: proceeds, gain: gain, profit: profit, total: total, annual: annual,
      gainPct: gain / basis, divPct: p.dividends / basis,
      breakeven: (basis + p.sellFee) / p.shares,
      tax: tax, afterTax: profit - tax, afterTaxPct: (profit - tax) / basis
    };
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function val(id, blankAs) {
    var t = el(id).value.trim();
    if (t === '' && blankAs !== undefined) return blankAs;
    var v = parseFloat(t);
    return isFinite(v) ? v : NaN;
  }
  function fix(x, dp) {
    if (Math.abs(x) < 0.5 * Math.pow(10, -dp)) x = 0;
    return x.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }).replace(/^-/, '−');
  }
  function pct(x) {
    if (!isFinite(x) || x > 1e6) return 'Over 100,000,000%';
    return fix(x * 100, 2) + '%';
  }
  function usd(x) { return money.format(Math.abs(x) < 0.005 ? 0 : x).replace(/^-/, '−'); }

  function clear(msg) {
    var error = el('srError');
    error.hidden = !msg;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { el(id).textContent = '–'; });
    el('srTaxRows').hidden = true;
    el('srNote').hidden = true;
  }

  function update() {
    var p = {
      shares: val('srShares'), buyPrice: val('srBuyPrice'), buyFee: val('srBuyFee', 0),
      sellPrice: val('srSellPrice'), sellFee: val('srSellFee', 0), dividends: val('srDividends', 0),
      taxRate: val('srTaxRate', 0)
    };
    var buyTxt = el('srBuyDate').value, sellTxt = el('srSellDate').value;
    var buy = parseDate(buyTxt), sell = parseDate(sellTxt);
    var msg = '';
    if (isNaN(p.shares) || p.shares <= 0 || p.shares > 1e10) msg = 'Enter a number of shares above 0.';
    else if (isNaN(p.buyPrice) || p.buyPrice < 0 || p.buyPrice > 1e7) msg = 'Enter a purchase price of $0 or more.';
    else if (isNaN(p.sellPrice) || p.sellPrice < 0 || p.sellPrice > 1e7) msg = 'Enter a sale price of $0 or more.';
    else if (isNaN(p.buyFee) || p.buyFee < 0 || p.buyFee > 1e9 || isNaN(p.sellFee) || p.sellFee < 0 || p.sellFee > 1e9) msg = 'Enter commissions of $0 or more.';
    else if (isNaN(p.dividends) || p.dividends < 0 || p.dividends > 1e12) msg = 'Enter dividends of $0 or more.';
    else if (isNaN(p.taxRate) || p.taxRate < 0 || p.taxRate > 100) msg = 'Enter a tax rate from 0% to 100%.';
    else if (p.shares * p.buyPrice + p.buyFee <= 0) msg = 'The total purchase cost must be above $0.';
    else if ((buyTxt && !buy) || (sellTxt && !sell)) msg = 'Enter valid dates, or leave both blank.';
    else if (buy && sell && sell.t < buy.t) msg = 'The sale date must be on or after the purchase date.';
    if (msg) { clear(msg); return; }
    clear('');

    var days = buy && sell ? Math.round((sell.t - buy.t) / DAY) : null;
    p.taxRate = p.taxRate / 100;
    p.days = days;
    var r = stockReturn(p);
    el('srTotalPct').textContent = pct(r.total);
    el('srAnnual').textContent = r.annual === null ? (days === 0 ? 'Needs 1+ day' : 'Add dates') : pct(r.annual);
    el('srGainLabel').textContent = r.gain < 0 ? 'Capital loss' : 'Capital gain';
    el('srGain').textContent = usd(r.gain);
    el('srProfit').textContent = usd(r.profit);
    el('srBasis').textContent = usd(r.basis);
    el('srProceeds').textContent = usd(r.proceeds);
    el('srGainPct').textContent = pct(r.gainPct);
    el('srDivPct').textContent = pct(r.divPct);
    el('srBreakeven').textContent = usd(r.breakeven);
    if (days !== null) {
      var yrs = days / 365;
      el('srHeld').textContent = days.toLocaleString('en-US') + (days === 1 ? ' day' : ' days') + ' (' + fix(yrs, 2) + ' years)';
      el('srTerm').textContent = isLongTerm(buy, sell) ? 'Long-term (held more than 1 year)' : 'Short-term (held 1 year or less)';
    } else {
      el('srHeld').textContent = 'Add dates';
      el('srTerm').textContent = 'Add dates';
    }
    if (p.taxRate > 0) {
      el('srTaxRows').hidden = false;
      el('srTax').textContent = usd(r.tax);
      el('srAfterTax').textContent = usd(r.afterTax);
      el('srAfterTaxPct').textContent = pct(r.afterTaxPct);
    }
    var note = el('srNote');
    if (r.gain < 0) {
      note.hidden = false;
      note.textContent = 'This trade shows a capital loss. Realized capital losses can offset capital gains and, within IRS limits, part of your ordinary income.';
    } else if (days !== null && days < 365 && r.annual !== null) {
      note.hidden = false;
      note.textContent = 'The holding period is under a year, so the annualized return assumes the same pace continues for a full year and can look much larger than the actual gain.';
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('srForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
